12	/**
13	 * Create an invoice.
14	 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} input
15	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, terms: string, dueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
16	 */
17	export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
18	  // Normalize customer ID
19	  const normalizedCustomerId = normalizeId(customerId);
20	
21	  // Validate customer exists
22	  const customerResult = getCustomer(normalizedCustomerId);
23	  if (!customerResult.ok) return customerResult;
24	  const customer = customerResult.value;
25	  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
26	
27	  // Validate issueDate is a real date in YYYY-MM-DD format
28	  if (!isValidDate(issueDate)) return fail('DATE_INVALID');
29	
30	  // Validate and calculate dueDate based on terms
31	  if (!['NET14', 'NET30', 'EOM'].includes(terms)) return fail('TERMS_INVALID');
32	
33	  let dueDate;
34	  if (terms === 'NET14') {
35	    dueDate = addDays(issueDate, 14);
36	  } else if (terms === 'NET30') {
37	    dueDate = addDays(issueDate, 30);
38	  } else {
39	    // EOM: last day of the month
40	    const date = new Date(issueDate + 'T00:00:00Z');
41	    const year = date.getUTCFullYear();
42	    const month = date.getUTCMonth();
43	    const lastDay = new Date(Date.UTC(year, month + 1, 0));
44	    dueDate = lastDay.toISOString().split('T')[0];
45	  }
46	
47	  // Validate lines is not empty
48	  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');
49	
50	  // Validate and enrich each line
51	  const enrichedLines = [];
52	  for (const line of lines) {
53	    // Validate qty is a positive integer
54	    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');
55	
56	    // Validate discountPercent if provided
57	    if (line.discountPercent !== undefined) {
58	      if (typeof line.discountPercent !== 'number' || line.discountPercent < 0 || line.discountPercent > 100) {
59	        return fail('DISCOUNT_INVALID');
60	      }
61	    }
62	
63	    // Get product details
64	    const productResult = getProduct(line.sku);
65	    if (!productResult.ok) return productResult;
66	
67	    const { sku, name, unitPrice, vatRate } = productResult.value;
68	    // Use explicit discountPercent if provided, otherwise use tier discount
69	    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;
70	    enrichedLines.push({
71	      sku,
72	      name,
73	      qty: line.qty,
74	      unitPrice,
75	      vatRate,
76	      discountPercent,
77	    });
78	  }
79	
80	  return ok({
81	    customerId: normalizedCustomerId,
82	    issueDate,
83	    terms,
84	    dueDate,
85	    status: 'draft',
86	    lines: enrichedLines,
87	  });
88	}
