147	/**
148	 * Remove a line from an invoice.
149	 * @param {{ status: string, lines: Array }} invoice
150	 * @param {string} sku
151	 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
152	 */
153	export function removeLine(invoice, sku) {
154	  // Validate status is 'draft'
155	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
156	
157	  // Check if line exists
158	  const lineIndex = invoice.lines.findIndex((l) => l.sku === sku);
159	  if (lineIndex < 0) return fail('LINE_NOT_FOUND');
160	
161	  // Check if it's the last line
162	  if (invoice.lines.length === 1) return fail('NO_LINES');
163	
164	  // Create new invoice without this line
165	  const newLines = invoice.lines.filter((_, i) => i !== lineIndex);
166	
167	  return ok({
168	    ...invoice,
169	    lines: newLines,
170	  });
171	}
