173	/**
174	 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
175	 * @param {{ status: string, issueDate: string }} invoice
176	 * @param {string[]} existingNumbers - Array of invoice numbers already used
177	 * @returns {{ ok: true, value: { number: string, status: string } } | { ok: false, error: string }}
178	 */
179	export function issueInvoice(invoice, existingNumbers) {
180	  // Validate status is 'draft'
181	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
182	
183	  // Get next invoice number
184	  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);
185	
186	  // Return new invoice with number and status changed to 'issued'
187	  return ok({
188	    ...invoice,
189	    number,
190	    status: 'issued',
191	  });
192	}
