1	import { ok, fail } from './result.js';
2	import { roundCents } from './money.js';
3	
4	/**
5	 * Calculate the total for a single line: qty * unitPrice.
6	 * @param {{ qty: number, unitPrice: number }} line
7	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
8	 */
9	export function lineTotal(line) {
10	  if (!line || typeof line !== 'object') return fail('LINE_INVALID');
11	  const { qty, unitPrice } = line;
12	  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');
13	  if (!Number.isInteger(unitPrice) || unitPrice < 0) return fail('LINE_INVALID');
14	
15	  return ok(roundCents(qty * unitPrice));
16	}
17	
18	/**
19	 * Calculate the discount for a single line (includes bulk discount if qty >= 10).
20	 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
21	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
22	 */
23	export function lineDiscount(line) {
24	  if (!line || typeof line !== 'object') return fail('LINE_INVALID');
25	
26	  // Validate discountPercent
27	  const discountPercent = line.discountPercent ?? 0;
28	  if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
29	    return fail('DISCOUNT_INVALID');
30	  }
31	
32	  // Get line total
33	  const lineTotalResult = lineTotal(line);
34	  if (!lineTotalResult.ok) return lineTotalResult;
35	
36	  const lineAmount = lineTotalResult.value;
37	
38	  // Calculate first discount (explicit or tier discount)
39	  const firstDiscount = roundCents(lineAmount * (discountPercent / 100));
40	
41	  // Calculate bulk discount (2.5% on what remains if qty >= 10)
42	  let bulkDiscount = 0;
43	  if (line.qty >= 10) {
44	    const amountAfterFirstDiscount = lineAmount - firstDiscount;
45	    bulkDiscount = roundCents(amountAfterFirstDiscount * 0.025);
46	  }
47	
48	  // Total discount is sum of both
49	  const totalDiscount = roundCents(firstDiscount + bulkDiscount);
50	  return ok(Math.max(0, totalDiscount)); // Clamp to 0
51	}
52	
53	/**
54	 * Calculate the VAT for a single line (on amount after discount).
55	 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
56	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
57	 */
58	export function lineVAT(line) {
59	  if (!line || typeof line !== 'object') return fail('LINE_INVALID');
60	
61	  // Get line total
62	  const lineTotalResult = lineTotal(line);
63	  if (!lineTotalResult.ok) return lineTotalResult;
64	
65	  // Get line discount
66	  const discountResult = lineDiscount(line);
67	  if (!discountResult.ok) return discountResult;
68	
69	  // Calculate amount after discount
70	  const amountAfterDiscount = lineTotalResult.value - discountResult.value;
71	
72	  // Get VAT rate
73	  const vatRate = line.vatRate ?? 0;
74	
75	  // Calculate VAT
76	  const vat = roundCents(amountAfterDiscount * (vatRate / 100));
77	  return ok(Math.max(0, vat)); // Clamp to 0
78	}
79	
80	/**
81	 * Calculate subtotal, discount, VAT, voucher, and total for an invoice.
82	 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }} invoice
83	 * @returns {{ ok: true, value: { subtotal: number, discount: number, vat: number, voucher: number, total: number } } | { ok: false, error: string }}
84	 */
85	export function invoiceTotals(invoice) {
86	  if (!invoice || typeof invoice !== 'object') return fail('INVOICE_INVALID');
87	  if (!Array.isArray(invoice.lines) || invoice.lines.length === 0) return fail('NO_LINES');
88	
89	  let subtotal = 0;
90	  let discount = 0;
91	  let vat = 0;
92	  for (const line of invoice.lines) {
93	    const lineResult = lineTotal(line);
94	    if (!lineResult.ok) return lineResult;
95	    subtotal += lineResult.value;
96	
97	    const discountResult = lineDiscount(line);
98	    if (!discountResult.ok) return discountResult;
99	    discount += discountResult.value;
100	
101	    const vatResult = lineVAT(line);
102	    if (!vatResult.ok) return vatResult;
103	    vat += vatResult.value;
104	  }
105	
106	  subtotal = roundCents(subtotal);
107	  discount = roundCents(discount);
108	  vat = roundCents(vat);
109	  const voucher = invoice.voucher?.amount ?? 0;
110	  const total = Math.max(0, roundCents(subtotal - discount + vat - voucher)); // Clamp to 0
111	
112	  return ok({
113	    subtotal,
114	    discount,
115	    vat,
116	    voucher,
117	    total,
118	  });
119	}
