1	import { ok, fail } from './result.js';
2	
3	/**
4	 * Round a (possibly fractional) number of cents to a whole cent, half to even (banker's rounding):
5	 * 124.5 -> 124, 125.5 -> 126, 2.4 -> 2, -0.5 -> 0.
6	 * @param {number} x
7	 * @returns {number}
8	 */
9	export function roundCents(x) {
10	  const r = Math.round(x * 1e6) / 1e6; // drop binary noise such as 124.49999999999999
11	  const floor = Math.floor(r);
12	  const diff = r - floor;
13	  if (diff > 0.5) return floor + 1;
14	  if (diff < 0.5) return floor === 0 ? 0 : floor;
15	  return floor % 2 === 0 ? floor : floor + 1;
16	}
17	
18	/**
19	 * Format cents as euros for people: 123456 -> "€1,234.56", -5 -> "-€0.05".
20	 * @param {number} cents
21	 * @returns {string}
22	 */
23	export function formatEuros(cents) {
24	  const sign = cents < 0 ? '-' : '';
25	  const abs = Math.abs(cents);
26	  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
27	  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
28	}
29	
30	/**
31	 * Parse a euro amount typed by a person ("12", "12.5", "1,234.56") into cents.
32	 * @param {string} text
33	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
34	 */
35	export function parseEuros(text) {
36	  const m = /^(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d{1,2}))?$/.exec(String(text).trim());
37	  if (!m) return fail('AMOUNT_INVALID');
38	  const euros = Number(m[1].replace(/,/g, ''));
39	  const cents = Number((m[2] ?? '').padEnd(2, '0'));
40	  return ok(euros * 100 + cents);
41	}
42	
43	/**
44	 * Exchange rates: units of each currency per euro.
45	 * 1 EUR = 1.085 USD = 0.8425 GBP
46	 */
47	export const RATES = {
48	  EUR: 1,
49	  USD: 1.085,
50	  GBP: 0.8425,
51	};
52	
53	/**
54	 * Convert an amount in EUR cents to another currency's cents.
55	 * @param {number} cents - Amount in EUR cents
56	 * @param {string} currency - Target currency (EUR, USD, GBP)
57	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
58	 */
59	export function convert(cents, currency) {
60	  if (!(currency in RATES)) {
61	    return fail('UNKNOWN_CURRENCY');
62	  }
63	
64	  const rate = RATES[currency];
65	  const convertedCents = roundCents(cents * rate);
66	
67	  return ok(convertedCents);
68	}
69	
70	/**
71	 * Format cents as money for a currency: 123456 USD -> "$1,234.56", 100 GBP -> "£1.00".
72	 * @param {number} cents - Amount in cents of the target currency
73	 * @param {string} currency - Currency (EUR, USD, GBP)
74	 * @returns {string} Formatted amount or empty string if currency unknown
75	 */
76	export function formatMoney(cents, currency) {
77	  const currencySymbols = {
78	    EUR: '€',
79	    USD: '$',
80	    GBP: '£',
81	  };
82	
83	  if (!(currency in currencySymbols)) {
84	    return '';
85	  }
86	
87	  const symbol = currencySymbols[currency];
88	  const sign = cents < 0 ? '-' : '';
89	  const abs = Math.abs(cents);
90	  const units = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
91	
92	  return `${sign}${symbol}${units}.${String(abs % 100).padStart(2, '0')}`;
93	}
