9	 */
10	export function listProducts() {
11	  return PRODUCTS.map((p) => ({ ...p }));
12	}
13	
14	/**
15	 * One product by SKU.
16	 * @param {string} sku
17	 */
18	export function getProduct(sku) {
19	  const p = PRODUCTS.find((x) => x.sku === sku);
20	  return p ? ok({ ...p }) : fail('UNKNOWN_SKU');
